/** 取下一個符合 ISO weekday（1=週一 … 7=週日）的未來日期 */
private function nextWeekday(int $isoDow): string
{
    $d = Carbon::now()->addDay();
    for ($i = 0; $i < 14; $i++) {
        if ((int) $d->dayOfWeekIso === $isoDow) {
            return $d->toDateString();
        }
        $d->addDay();
    }
    throw new \RuntimeException("Cannot find weekday {$isoDow} in next 14 days");
}

